import React from 'react';
import { Audio, Sequence, useCurrentFrame, staticFile, interpolate } from 'remotion';
import { SFX_CUES } from '../sfxCues';
import { beat } from '../motion/beat';

const LARGE_CUES = ['boom', 'stamp', 'whoosh', 'ding'];

export const SfxTrack: React.FC = () => {
  const frame = useCurrentFrame();

  // User specified music structure
  let musicVol = 0.6;
  
  if (frame >= beat(40) && frame < beat(46)) {
    // 20s to 23s: hum xử lý
    musicVol = 0.2;
  } else if (frame >= beat(72) && frame < beat(106)) {
    // 36s to 53s: tiếng gõ phím
    musicVol = 0.2;
  } else if (frame >= beat(187) && frame < beat(196)) {
    // 93.5s: lên cao trào
    musicVol = 0.8;
  } else if (frame >= beat(196)) {
    // 98s: ngắt
    musicVol = 0;
  }

  // Smooth interpolation for ducking transitions
  if (frame >= beat(38) && frame < beat(40)) {
    musicVol = interpolate(frame, [beat(38), beat(40)], [0.6, 0.2], { extrapolateRight: 'clamp' });
  }
  if (frame >= beat(46) && frame < beat(48)) {
    musicVol = interpolate(frame, [beat(46), beat(48)], [0.2, 0.6], { extrapolateRight: 'clamp' });
  }
  
  if (frame >= beat(70) && frame < beat(72)) {
    musicVol = interpolate(frame, [beat(70), beat(72)], [0.6, 0.2], { extrapolateRight: 'clamp' });
  }
  if (frame >= beat(106) && frame < beat(108)) {
    musicVol = interpolate(frame, [beat(106), beat(108)], [0.2, 0.6], { extrapolateRight: 'clamp' });
  }
  
  if (frame >= beat(185) && frame < beat(187)) {
    musicVol = interpolate(frame, [beat(185), beat(187)], [0.6, 0.8], { extrapolateRight: 'clamp' });
  }
  if (frame >= beat(195.5) && frame < beat(196)) {
    // Sharp cut at 98s
    musicVol = interpolate(frame, [beat(195.5), beat(196)], [0.8, 0], { extrapolateRight: 'clamp' });
  }

  return (
    <>
      {/* Background Music (Placeholder for the real one) */}
      <Audio src={staticFile('audio/music.wav')} volume={musicVol} />

      {/* SFX Tracks */}
      {SFX_CUES.map((cue, i) => {
        const startFrame = beat(cue.beat) - (cue.leadFrames ?? 0);
        return (
          <Sequence key={i} from={startFrame}>
            <Audio src={staticFile(`audio/sfx-${cue.name}.wav`)} volume={cue.volume} />
          </Sequence>
        );
      })}
    </>
  );
};
